style.css:
/* Form-local overrides; keep legal links in the sentence despite template action sizing. */
.af-form { background: transparent !important; color: #dad8cf; }
h1 { margin: 0 0 24px !important; color: #f1ece2; font: 600 24px/1.25 -apple-system, BlinkMacSystemFont, sans-serif !important; }
label, p { margin: 0 !important; padding: 0 !important; font-size: 14px !important; line-height: 1.5 !important; background: transparent !important; }
input[type=checkbox] { width: 18px !important; height: 18px !important; margin-top: 2px !important; align-self: flex-start; accent-color: #bfd79a; }
a[href="https://legal.rillora.xyz/terms"], a[href="https://legal.rillora.xyz/privacy"] { display: inline !important; min-height: 0 !important; padding: 0 !important; color: #dad8cf !important; font-size: inherit !important; line-height: inherit !important; text-decoration: underline !important; text-underline-offset: 2px; }
button, .af-button { align-items: center !important; justify-content: center !important; width: 100%; min-height: 48px !important; border: 0; border-radius: 10px; background: #cb704c; color: #171c1c; font: 600 16px/1.4 -apple-system, BlinkMacSystemFont, sans-serif !important; text-align: center !important; }
button:focus-visible, input:focus-visible, a:focus-visible { outline: 2px solid #bfd79a; outline-offset: 3px; }
label { color: #b8bab2; }
[role=alert] { background: #352722 !important; border-color: #804535 !important; color: #ffb5a5 !important; }
[role=alert] p, [role=alert] span { color: inherit !important; }
